with cleaned as (select id, customer_id, store_id, order_date, channel, amount, discount, shipping_fee, lower(channel) as channel_lower from orders where store_id is not null and order_date < '2024-03-01') select *, last_value(channel) ignore nulls over (partition by customer_id order by order_date, id rows between unbounded preceding and current row) as last_known_channel, corr(shipping_fee, amount) over (partition by store_id) as corr_shipping_fee_amount from cleaned;
